// Parity of the Qwen3.5 tokenizer (src/qwen3_5/tokenizer.ts over the shared byte-level BPE
// src/text/qwen2-tokenizer.ts) and of the chat prompt MOSS-Image renders (src/qwen3_5/chat.ts) with
// the Python source of truth. No GPU and no asset needed (the full asset is checked too when the
// distribution mirror `models/karume-moss-image/` is present — its `tokenizer` asset, read through
// the manifest, ADR 0139).
//
// The fixture `qwen3_5/tokenizer-cases.json` is generated by `tools/export-recipes/qwen3_5/tokenizer.py`
// from the tokenizer MOSS-Image pins: the rendered prompts are transformers 5.14.1's
// `apply_chat_template`, the ids its `AutoTokenizer` (`truncation=True, max_length=4096`), and it
// carries the vocabulary / merges subset the cases need plus the whole Unicode tables.
//
// The behaviour pinned: the same prompt renders the same string and gives the same ids as upstream;
// over-length input is refused unless the caller asks to truncate like upstream.

import { readTextFile } from "@karume/test-support/fs";
import { describe, it } from "vite-plus/test";
import { assert, assertEquals, assertThrows } from "@std/assert";
import { ModelInputError } from "../src/errors.ts";
import { renderQwen3_5ChatPrompt } from "../src/qwen3_5/chat.ts";
import {
  parseQwen3_5TokenizerAsset,
  QWEN3_5_TOKENIZER_FORMAT,
  type Qwen3_5Overflow,
  Qwen3_5Tokenizer,
} from "../src/qwen3_5/tokenizer.ts";
import { parseCodeRanges } from "../src/text/code-ranges.ts";
import { pythonStrip } from "../src/text/python-strip.ts";
import { normalizeNfc, type Qwen2Assets } from "../src/text/qwen2-tokenizer.ts";
import { mirrorPresent, mirrorRoot, readMirrorAsset } from "./helpers/mirror.ts";

type PromptCase = {
  readonly id: string;
  readonly why: string;
  readonly prompt: string;
  /** Accepted by the template: upstream's rendered string, ids (truncated) and untruncated count. */
  readonly rendered?: string;
  readonly ids?: number[];
  readonly tokens?: number;
  /** Refused by the template. */
  readonly reject?: "template";
};

type TextCase = {
  readonly id: string;
  readonly why: string;
  readonly text: string;
  readonly ids: number[];
};

type Fixture = {
  readonly assetFormat: string;
  readonly maxLength: number;
  readonly qwen: {
    readonly addedTokens: [string, number][];
    readonly classes: { letter: unknown; number: unknown; space: unknown };
    readonly caseFold: [number, number][];
    readonly nfcSegments: unknown;
    readonly nfcCases: [string, string][];
    readonly vocab: Record<string, number>;
    readonly merges: [string, string, number][];
  };
  readonly pythonSpace: number[];
  readonly promptCases: PromptCase[];
  readonly textCases: TextCase[];
};

const fixture = JSON.parse(
  await readTextFile(new URL("./fixtures/qwen3_5/tokenizer-cases.json", import.meta.url)),
) as Fixture;

const assets: Qwen2Assets = {
  vocab: new Map(Object.entries(fixture.qwen.vocab)),
  merges: new Map(fixture.qwen.merges.map(([left, right, rank]) => [`${left} ${right}`, rank])),
  addedTokens: new Map(fixture.qwen.addedTokens),
  caseFold: new Map(fixture.qwen.caseFold),
  nfcSegments: parseCodeRanges(fixture.qwen.nfcSegments, "nfcSegments"),
  classes: {
    letter: parseCodeRanges(fixture.qwen.classes.letter, "letter"),
    number: parseCodeRanges(fixture.qwen.classes.number, "number"),
    space: parseCodeRanges(fixture.qwen.classes.space, "space"),
  },
  maxLength: fixture.maxLength,
};
const tokenizer = new Qwen3_5Tokenizer(assets);

type AcceptedCase = PromptCase & { rendered: string; ids: number[]; tokens: number };
const accepted = fixture.promptCases.filter(
  (testCase): testCase is AcceptedCase => testCase.rendered !== undefined,
);
const refused = fixture.promptCases.filter((testCase) => testCase.reject !== undefined);
const withinBound = accepted.filter((testCase) => testCase.tokens <= fixture.maxLength);
const overBound = accepted.filter((testCase) => testCase.tokens > fixture.maxLength);

const caseById = (id: string): AcceptedCase => {
  const found = accepted.find((testCase) => testCase.id === id);
  if (found === undefined) throw new Error(`the fixture has no accepted prompt case ${id}`);
  return found;
};

/**
 * The distribution's full asset (the whole vocabulary — checked against every case when present):
 * the `tokenizer` asset of MOSS-Image's mirror, the recipe's `qwen3_5.tokenizer` output as shipped.
 */
const MOSS_MIRROR = mirrorRoot("karume-moss-image");
const MIRROR_PRESENT = mirrorPresent(MOSS_MIRROR);
const fullAsset = MIRROR_PRESENT
  ? new TextDecoder().decode(await readMirrorAsset(MOSS_MIRROR, "tokenizer", { model: "sft" }))
  : undefined;
const FULL_ASSET_SKIP = MIRROR_PRESENT
  ? ""
  : ` (SKIP: no mirror ${MOSS_MIRROR.pathname} — hf download hdae/karume-moss-image` +
    " --local-dir models/karume-moss-image)";
if (!MIRROR_PRESENT) {
  console.warn(`[karume] the full-asset check of the Qwen3.5 tokenizer${FULL_ASSET_SKIP}`);
}

/** The ids of the template around the content (`<|im_start|>user\n` … `<|im_end|>\n…<think>\n`). */
const TEMPLATE_HEAD = 3;
const TEMPLATE_TAIL = 7;
const IM_END = 248046;
const THINK = 248068;
const THINK_END = 248069;
const END_OF_TEXT = 248044;

describe("the fixture", () => {
  it("holds every kind of case (a broken fixture does not pass as zero cases)", () => {
    assertEquals(fixture.assetFormat, QWEN3_5_TOKENIZER_FORMAT);
    assertEquals(fixture.maxLength, 4096);
    assertEquals(fixture.qwen.addedTokens.length, 33);
    assert(withinBound.length >= 25, `${withinBound.length} accepted prompt cases`);
    assert(overBound.length >= 2, `${overBound.length} over-length prompt cases`);
    assert(refused.length >= 1, `${refused.length} refused prompt cases`);
    assert(fixture.textCases.length >= 60, `${fixture.textCases.length} text cases`);
  });
});

describe("renderQwen3_5ChatPrompt renders the string upstream's apply_chat_template renders", () => {
  for (const testCase of accepted) {
    it(`[${testCase.id}] ${testCase.why}`, () => {
      assertEquals(renderQwen3_5ChatPrompt(testCase.prompt), testCase.rendered);
    });
  }

  it("renders the empty prompt as the bare template of 10 tokens", () => {
    const empty = caseById("empty");
    assertEquals(empty.rendered, "<|im_start|>user\n<|im_end|>\n<|im_start|>assistant\n<think>\n");
    assertEquals(
      [...tokenizer.tokenize(renderQwen3_5ChatPrompt(""))],
      [248045, 846, 198, 248046, 198, 248045, 74455, 198, 248068, 198],
    );
  });

  for (const testCase of refused) {
    it(`[${testCase.id}] refuses what upstream's template refuses: ${testCase.why}`, () => {
      assertThrows(() => renderQwen3_5ChatPrompt(testCase.prompt), ModelInputError, "tool result");
    });
  }

  it("names the caller's label and rejects a prompt that is not a string", () => {
    assertThrows(
      () => renderQwen3_5ChatPrompt("<tool_response>x</tool_response>", "negative prompt"),
      ModelInputError,
      "negative prompt:",
    );
    assertThrows(
      () => renderQwen3_5ChatPrompt(42 as unknown as string),
      ModelInputError,
      "not a string",
    );
  });
});

describe("Qwen3_5Tokenizer gives upstream's ids for a rendered prompt", () => {
  for (const testCase of withinBound) {
    it(`[${testCase.id}] ${testCase.why}`, () => {
      assertEquals([...tokenizer.tokenize(testCase.rendered)], testCase.ids);
    });
  }

  it("turns special-token spellings typed in the prompt into control tokens, as upstream", () => {
    const { ids } = caseById("special_tokens");
    const content = ids.slice(TEMPLATE_HEAD, ids.length - TEMPLATE_TAIL);
    const controls = content.filter((id) => id >= END_OF_TEXT);
    assertEquals(controls, [IM_END, THINK, THINK_END, END_OF_TEXT]);
  });

  it("does not cut out a partial spelling of an added token", () => {
    const { ids } = caseById("special_lookalike");
    const content = ids.slice(TEMPLATE_HEAD, ids.length - TEMPLATE_TAIL);
    assertEquals(
      content.filter((id) => id >= END_OF_TEXT),
      [],
    );
  });
});

describe("Qwen3_5Tokenizer over the length bound", () => {
  it("accepts exactly maxLength tokens", () => {
    const exact = caseById("boundary_4096");
    assertEquals(exact.tokens, fixture.maxLength);
    assertEquals([...tokenizer.tokenize(exact.rendered)], exact.ids);
  });

  for (const testCase of overBound) {
    it(`[${testCase.id}] rejects by default (${testCase.tokens} tokens)`, () => {
      assertThrows(
        () => tokenizer.tokenize(testCase.rendered, { label: "prompt" }),
        ModelInputError,
        `prompt: the token count exceeds the upper bound ${fixture.maxLength}`,
      );
    });

    it(`[${testCase.id}] truncates exactly as upstream with overflow "truncate"`, () => {
      const ids = [...tokenizer.tokenize(testCase.rendered, { overflow: "truncate" })];
      assertEquals(ids.length, fixture.maxLength);
      assertEquals(ids, testCase.ids);
    });
  }

  it("drops the template's tail when truncating, as upstream does", () => {
    const over = caseById("boundary_4097");
    const ids = [...tokenizer.tokenize(over.rendered, { overflow: "truncate" })];
    // The last `\n` after `<think>` is cut; `<think>` is the last id kept.
    assertEquals(ids.at(-1), THINK);
  });

  it("rejects an unknown overflow policy", () => {
    assertThrows(
      () => tokenizer.tokenize("cat", { overflow: "cut" as Qwen3_5Overflow }),
      ModelInputError,
      "unknown overflow policy",
    );
  });

  it("rejects an unpaired surrogate as an input error", () => {
    assertThrows(() => tokenizer.tokenize("a\ud800b"), ModelInputError, "unpaired surrogate");
  });
});

describe("Qwen3_5Tokenizer on its own gives upstream's ids for raw text", () => {
  for (const testCase of fixture.textCases) {
    it(`[${testCase.id}] ${testCase.why}`, () => {
      assertEquals([...tokenizer.tokenize(testCase.text)], testCase.ids);
    });
  }
});

describe("pythonStrip strips what Python's str.strip() strips", () => {
  it("removes exactly the str.isspace() code points (every BMP code point)", () => {
    const space = new Set(fixture.pythonSpace);
    assertEquals(space.size, 29);
    for (let cp = 0; cp <= 0xffff; cp++) {
      if (cp >= 0xd800 && cp <= 0xdfff) continue;
      const ch = String.fromCharCode(cp);
      assertEquals(pythonStrip(`${ch}x${ch}`), space.has(cp) ? "x" : `${ch}x${ch}`, `U+${cp}`);
    }
    // Every Python whitespace is in the BMP, so no astral code point is stripped.
    assert(fixture.pythonSpace.every((cp) => cp <= 0xffff));
  });

  it("differs from String.prototype.trim where Python differs from JS", () => {
    assertEquals(pythonStrip("﻿x﻿"), "﻿x﻿");
    assertEquals("﻿x﻿".trim(), "x");
    assertEquals(pythonStrip("\x1cx\x85"), "x");
    assertEquals("\x1cx\x85".trim(), "\x1cx\x85");
  });
});

describe("the Qwen3.5 tables reproduce the canonical NFC", () => {
  it("matches the canonical output on the pairs plain normalize() gets wrong", () => {
    assert(fixture.qwen.nfcCases.length > 100, `${fixture.qwen.nfcCases.length} NFC pairs`);
    for (const [input, want] of fixture.qwen.nfcCases) {
      assertEquals(normalizeNfc(input, assets.nfcSegments), want, JSON.stringify(input));
    }
  });
});

/** A small asset in the recipe's format (byte-level: `Ġ` is the space). */
const minimalAsset = (patch: Record<string, unknown> = {}): Record<string, unknown> => ({
  format: QWEN3_5_TOKENIZER_FORMAT,
  source: { repo: "test", revision: "0".repeat(40), subfolder: "tokenizer", files: {} },
  versions: { tokenizers: "0", transformers: "0" },
  maxLength: 3,
  addedTokens: [["<|im_end|>", 7]],
  classes: {
    letter: [
      [0x41, 0x5a],
      [0x61, 0x7a],
    ],
    number: [[0x30, 0x39]],
    space: [
      [0x09, 0x0d],
      [0x20, 0x20],
    ],
  },
  caseFold: [],
  nfcSegments: [],
  vocabText: "c\na\nt\nca\ncat\nĠ\nĠcat",
  vocabCount: 7,
  mergesText: "c a\nca t\nĠ cat",
  mergesCount: 3,
  ...patch,
});

describe("parseQwen3_5TokenizerAsset", () => {
  it("builds a tokenizer from the asset JSON", () => {
    const tiny = new Qwen3_5Tokenizer(parseQwen3_5TokenizerAsset(minimalAsset()));
    assertEquals(tiny.maxLength, 3);
    assertEquals([...tiny.tokenize("cat cat<|im_end|>")], [4, 6, 7]);
    assertThrows(() => tiny.tokenize("cat cat cat cat"), ModelInputError, "upper bound 3");
    assertEquals([...tiny.tokenize("cat cat cat cat", { overflow: "truncate" })], [4, 6, 6]);
  });

  it("does not read another format version", () => {
    for (const format of ["karume-qwen3_5-tokenizer/2", "karume-umt5-tokenizer/1"]) {
      assertThrows(
        () => parseQwen3_5TokenizerAsset(minimalAsset({ format })),
        Error,
        `cannot read format ${format}`,
      );
    }
    assertThrows(
      () => parseQwen3_5TokenizerAsset(minimalAsset({ format: undefined })),
      Error,
      "tokenizer.format",
    );
  });

  it("refuses a broken table as an asset error, not an input error", () => {
    const rejected: readonly [string, Record<string, unknown>, string][] = [
      ["a merge line missing", { mergesCount: 4 }, "does not match"],
      [
        "a duplicated vocabulary line",
        { vocabText: "c\na\nt\nca\ncat\nĠ\nĠ" },
        "tokenizer.vocabText",
      ],
      ["no maxLength", { maxLength: undefined }, "maxLength"],
    ];
    for (const [label, patch, message] of rejected) {
      const error = assertThrows(
        () => parseQwen3_5TokenizerAsset(minimalAsset(patch)),
        Error,
        message,
        label,
      );
      assert(!(error instanceof ModelInputError), `an asset error is not an input error: ${label}`);
    }
  });
});

describe.skipIf(fullAsset === undefined)(`the distribution's full asset${FULL_ASSET_SKIP}`, () => {
  it("gives the same ids as the fixture's subset on every case", () => {
    const full = new Qwen3_5Tokenizer(parseQwen3_5TokenizerAsset(JSON.parse(fullAsset as string)));
    assertEquals(full.maxLength, fixture.maxLength);
    for (const testCase of accepted) {
      const ids = full.tokenize(testCase.rendered, { overflow: "truncate" });
      assertEquals([...ids], testCase.ids, testCase.id);
    }
    for (const testCase of fixture.textCases) {
      assertEquals([...full.tokenize(testCase.text)], testCase.ids, testCase.id);
    }
  });
});
